}

@CacheableTask
abstract class GenerateAssertjAssertionsTask : DefaultTask() {
    @get:Classpath
    abstract val classDirs: ConfigurableFileCollection

    @get:Classpath
    abstract val classpath: ConfigurableFileCollection

    @get:OutputDirectory
    abstract val outputDir: DirectoryProperty

    @get:Inject
    abstract val fs: FileSystemOperations

    @TaskAction
    fun generate() {
        val outDir = outputDir.get().asFile
        fs.delete { delete(outDir) }
        outDir.mkdirs()

        val classDirFiles = classDirs.files
        val cp = classpath.files + classDirFiles
        val loader = URLClassLoader(
            cp.map { it.toURI().toURL() }.toTypedArray(),
            javaClass.classLoader,
        )

        try {
            val classNames = classDirFiles.flatMap { dir ->
                dir.walkTopDown()
                    .filter { it.isFile && it.extension == "class" }
                    .map { file ->
                        file.relativeTo(dir).invariantSeparatorsPath
                            .removeSuffix(".class")
                            .replace('/', '.')
                    }
                    .toList()
            }.toSet()
                .filter { it.startsWith("io.camunda.zeebe.protocol.record") }
                .filterNot {
                    it.endsWith(".package-info") ||
                        it.contains(".Immutable") ||
                        it.endsWith("Assert") ||
                        it.endsWith("Assertions")
                }

            val types = classNames
                .map { loader.loadClass(it) }
                .filterNot { it.simpleName == "package-info" }
                .filterNot { it.isSynthetic }
                .filterNot { Modifier.isPrivate(it.modifiers) }
                .map { TypeToken.of(it) }
                .toSet()
            val converter = ClassToClassDescriptionConverter()
            val generator = BaseAssertionGenerator()
            generator.setDirectoryWhereAssertionFilesAreGenerated(outDir)

            val descriptions = types.map { type ->
                val description = converter.convertToClassDescription(type)
                generator.generateCustomAssertionFor(description)
                description
            }.toSet()

            generator.generateAssertionsEntryPointClassFor(
                descriptions,
                AssertionsEntryPointType.STANDARD,
                null,
            )
            generator.generateAssertionsEntryPointClassFor(
                descriptions,
                AssertionsEntryPointType.SOFT,
                null,
            )
        } finally {
            loader.close()
        }
    }
}

abstract class PatchRecordAssertTask : DefaultTask() {
    @get:InputFiles
    abstract val sourceDir: DirectoryProperty

    @get:OutputFile
    abstract val recordAssertFile: RegularFileProperty

    @TaskAction
    fun patch() {
        val file = recordAssertFile.get().asFile
        if (!file.exists()) {
            return
        }
        val updated = file.readText()
            .replace("T value", "RecordValue value")
            .replace("T actualValue", "RecordValue actualValue")
        file.writeText(updated)
    }
}

val assertjGeneratedDir = layout.buildDirectory.dir("generated-sources/assertj-assertions")
val generatedAssertjClassesDir = layout.buildDirectory.dir("generated-classes/assertj")

// Use stable output locations for the producer projects instead of reading their mutable model.
// The project dependencies below still provide the compile classpath and task graph edges.
val protocolOutput = layout.settingsDirectory.dir("zeebe/protocol/build/classes/java/main")
val securityProtocolOutput =
  layout.settingsDirectory.dir("security/security-protocol/build/classes/java/main")
val protocolCompileClasspath = configurations.compileClasspath

val generateAssertjAssertions =
  tasks.register<GenerateAssertjAssertionsTask>("generateAssertjAssertions") {
    group = "code generation"
    description = "Generate AssertJ assertions for Zeebe protocol record types"

    dependsOn(":zeebe-protocol:classes", ":camunda-security-protocol:classes")

    classDirs.from(protocolOutput, securityProtocolOutput)
    classpath.from(protocolCompileClasspath)
    outputDir.set(assertjGeneratedDir)
}

val patchRecordAssert = tasks.register<PatchRecordAssertTask>("patchRecordAssert") {
    group = "code generation"
    description = "Patch generated RecordAssert generic types"
    dependsOn(generateAssertjAssertions)

    sourceDir.set(assertjGeneratedDir)
    recordAssertFile.set(
        layout.buildDirectory.file(
            "generated-sources/assertj-assertions/io/camunda/zeebe/protocol/record/RecordAssert.java",
        ),
    )
}

dependencies {
    implementation(project(":zeebe-protocol"))
    implementation(project(":camunda-security-protocol"))
    implementation(libs.org.assertj.assertj.core)
    implementation(libs.javax.annotation.javax.annotation.api)
}

val compileGeneratedAssertjJava =
  tasks.register<JavaCompile>("compileGeneratedAssertjJava") {
    dependsOn(patchRecordAssert)
    source(assertjGeneratedDir)
    classpath = files(sourceSets["main"].compileClasspath, protocolOutput, securityProtocolOutput)
    destinationDirectory.set(generatedAssertjClassesDir)
    options.encoding = "utf-8"
}

sourceSets.named("main") {
    output.dir(mapOf("builtBy" to compileGeneratedAssertjJava), generatedAssertjClassesDir)
}

tasks.named("classes") {
    dependsOn(compileGeneratedAssertjJava)
}

tasks.named<Jar>("jar") {
    duplicatesStrategy = DuplicatesStrategy.EXCLUDE
}

val generatedAssertions = configurations.create("generatedAssertions") {
    isCanBeConsumed = true
    isCanBeResolved = false
}

artifacts {
    add("generatedAssertions", generatedAssertjClassesDir) {
        builtBy(compileGeneratedAssertjJava)
    }
}

description = "Zeebe Protocol AssertJ Assertions"
